package com.primehr.succession.domain;
import com.primehr.integration.humanresource.HumanResourceAssessmentSubject;import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="succession_candidate",uniqueConstraints=@UniqueConstraint(name="uk_succession_candidate_cycle_target_employee",columnNames={"agency_id","cycle_id","designation_id","employee_id"}))
public class SuccessionCandidate extends RspAuditedEntity{
 public enum IntakeType{AUTHORIZED_NOMINATION,SELF_EXPRESSION_OF_INTEREST} public enum Status{DRAFT,NOTICE_SENT,CONSENTED,SUBMITTED,ELIGIBLE,INELIGIBLE,WITHDRAWN}
 @Column(name="cycle_id",nullable=false,length=36)private String cycleId;@Column(name="designation_id",nullable=false,length=36)private String designationId;@Column(name="intake_type",nullable=false,length=40)@Enumerated(EnumType.STRING)private IntakeType intakeType;@Column(name="initiated_by",nullable=false,length=100)private String initiatedBy;
 @Column(name="employee_id",nullable=false)private Long employeeId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Column(name="employee_name",nullable=false,length=300)private String employeeName;@Column(name="appointment_id",nullable=false)private Long appointmentId;@Column(name="current_job_position_id")private Long currentJobPositionId;@Column(name="current_plantilla_id")private Long currentPlantillaId;@Column(name="employee_fingerprint",nullable=false,length=120)private String employeeFingerprint;
 @Column(name="target_type",nullable=false,length=20)private String targetType;@Column(name="target_id",nullable=false)private Long targetId;@Column(name="target_job_position_id",nullable=false)private Long targetJobPositionId;@Column(name="target_position_name",nullable=false,length=250)private String targetPositionName;@Column(name="target_plantilla_id")private Long targetPlantillaId;@Column(name="target_plantilla_name",length=250)private String targetPlantillaName;@Column(name="target_fingerprint",nullable=false,length=120)private String targetFingerprint;
 @Column(name="nomination_reason",nullable=false,length=4000)private String nominationReason;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="notice_text",length=4000)private String noticeText;@Column(name="notice_sent_by",length=100)private String noticeSentBy;@Column(name="notice_sent_at")private Instant noticeSentAt;@Column(name="consent_statement",length=4000)private String consentStatement;@Column(name="consented_at")private Instant consentedAt;@Column(name="submitted_by",length=100)private String submittedBy;@Column(name="submitted_at")private Instant submittedAt;@Column(name="eligibility_outcome",length=20)private String eligibilityOutcome;@Column(name="eligibility_reason",length=4000)private String eligibilityReason;@Column(name="eligibility_reviewed_by",length=100)private String eligibilityReviewedBy;@Column(name="eligibility_reviewed_at")private Instant eligibilityReviewedAt;@Column(name="withdrawn_by",length=100)private String withdrawnBy;@Column(name="withdrawn_at")private Instant withdrawnAt;@Column(name="withdrawal_reason",length=2000)private String withdrawalReason;
 protected SuccessionCandidate(){} public SuccessionCandidate(String a,String cycle,SuccessionCriticalPositionDesignation d,IntakeType type,String actor,HumanResourceAssessmentSubject e,String reason){super(a);cycleId=requiredText(cycle,"cycleId");designationId=d.getId();intakeType=java.util.Objects.requireNonNull(type);initiatedBy=requiredText(actor,"actor");employeeId=e.employeeId();employeeNo=requiredText(e.employeeNo(),"employeeNo");employeeName=requiredText(e.displayName(),"employeeName");appointmentId=java.util.Objects.requireNonNull(e.appointmentId());currentJobPositionId=e.jobPositionId();currentPlantillaId=e.plantillaId();employeeFingerprint=requiredText(e.sourceFingerprint(),"employeeFingerprint");targetType=d.getTargetType().name();targetId=d.getTargetId();targetJobPositionId=d.getJobPositionId();targetPositionName=d.getPositionName();targetPlantillaId=d.getPlantillaId();targetPlantillaName=d.getPlantillaName();targetFingerprint=d.getSourceFingerprint();nominationReason=requiredText(reason,"nominationReason");status=Status.DRAFT;}
 public void updateReason(String reason){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Only draft candidate intake may be changed");nominationReason=requiredText(reason,"nominationReason");}
 public void sendNotice(String actor,String text,Instant at){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Notice may only be sent for draft candidate intake");noticeText=requiredText(text,"noticeText");noticeSentBy=requiredText(actor,"actor");noticeSentAt=at;status=Status.NOTICE_SENT;}
 public void consent(String actor,String statement,Instant at){if(status!=Status.NOTICE_SENT)throw new IllegalLifecycleTransitionException("Consent requires prior notice");if(!employeeNo.equalsIgnoreCase(actor))throw new IllegalArgumentException("Only the candidate may consent");consentStatement=requiredText(statement,"consentStatement");consentedAt=at;status=Status.CONSENTED;}
 public void submit(String actor,Instant at){if(status!=Status.CONSENTED)throw new IllegalLifecycleTransitionException("Candidate intake requires consent before submission");submittedBy=requiredText(actor,"actor");submittedAt=at;status=Status.SUBMITTED;}
 public void decideEligibility(boolean eligible,String actor,String reason,Instant at){if(status!=Status.SUBMITTED)throw new IllegalLifecycleTransitionException("Only submitted candidate intake may receive an eligibility decision");if(employeeNo.equalsIgnoreCase(actor))throw new IllegalArgumentException("Candidate cannot decide their own eligibility");eligibilityOutcome=eligible?"ELIGIBLE":"INELIGIBLE";eligibilityReason=requiredText(reason,"reason");eligibilityReviewedBy=requiredText(actor,"actor");eligibilityReviewedAt=at;status=eligible?Status.ELIGIBLE:Status.INELIGIBLE;}
 public void withdraw(String actor,String reason,Instant at){if(status==Status.WITHDRAWN)throw new IllegalLifecycleTransitionException("Candidate intake is already withdrawn");if(!employeeNo.equalsIgnoreCase(actor)&&!initiatedBy.equalsIgnoreCase(actor))throw new IllegalArgumentException("Only the candidate or nominator may withdraw this intake");withdrawnBy=requiredText(actor,"actor");withdrawalReason=requiredText(reason,"reason");withdrawnAt=at;status=Status.WITHDRAWN;}
 public String getCycleId(){return cycleId;}public String getDesignationId(){return designationId;}public IntakeType getIntakeType(){return intakeType;}public String getInitiatedBy(){return initiatedBy;}public Long getEmployeeId(){return employeeId;}public String getEmployeeNo(){return employeeNo;}public String getEmployeeName(){return employeeName;}public Long getAppointmentId(){return appointmentId;}public Long getCurrentJobPositionId(){return currentJobPositionId;}public Long getCurrentPlantillaId(){return currentPlantillaId;}public String getEmployeeFingerprint(){return employeeFingerprint;}public String getTargetType(){return targetType;}public Long getTargetId(){return targetId;}public Long getTargetJobPositionId(){return targetJobPositionId;}public String getTargetPositionName(){return targetPositionName;}public Long getTargetPlantillaId(){return targetPlantillaId;}public String getTargetPlantillaName(){return targetPlantillaName;}public String getTargetFingerprint(){return targetFingerprint;}public String getNominationReason(){return nominationReason;}public Status getStatus(){return status;}public String getNoticeText(){return noticeText;}public String getNoticeSentBy(){return noticeSentBy;}public Instant getNoticeSentAt(){return noticeSentAt;}public String getConsentStatement(){return consentStatement;}public Instant getConsentedAt(){return consentedAt;}public String getSubmittedBy(){return submittedBy;}public Instant getSubmittedAt(){return submittedAt;}public String getEligibilityOutcome(){return eligibilityOutcome;}public String getEligibilityReason(){return eligibilityReason;}public String getEligibilityReviewedBy(){return eligibilityReviewedBy;}public Instant getEligibilityReviewedAt(){return eligibilityReviewedAt;}public String getWithdrawnBy(){return withdrawnBy;}public Instant getWithdrawnAt(){return withdrawnAt;}public String getWithdrawalReason(){return withdrawalReason;}
}
